head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[calendar > M > setDisableBeforeDate]<br/>Calendar 컴포넌트에서 기준 날짜 이전의 날짜를 선택 불가능하도록 비활성화합니다.",
    "validation" : [
        "date(필수) 파라미터로 비활성화 기준 날짜를 'yyyyMMdd' 8자리 포맷의 문자열로 설정합니다.",
        "비활성화된 날짜 셀에는 'w2calendar_date_disable' CSS 클래스가 적용됩니다.",
        "calendarValueType=yearMonth 일때 setDisableBeforeDate() 메소드로 제한 날짜를 설정할 수 있지만 컴포넌트에서 해당 년/월의 선택을 제한하지 않습니다.",
        "컴포넌트에 설정된 기준 날짜 이후의 날짜에 취소선이 표시되며 해당 날짜는 선택할 수 없습니다.",
        "년/월 탐색은 제한하지 않습니다.",
        "날짜 선택 제한과 관련된 메소드는 중복으로 적용됩니다."
    ]
}



scwin.onpageload = function () {
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {
        calendarValueType : con_calendarValueType.getText()
    }

    let cList = $c.gcm.createCList(properties);

    // createBasicCalendar 내부에서 gotoCalendar('20251111') 호출 → 초기 표시 달: 2025-11
    await $c.gcm.createBasicCalendar(cList);
}



// [공통] 비활성 날짜 셀(.w2calendar_date_disable) 정보 출력
scwin.getDisableInfo = function (callLog) {
    let disabledTds = target1.render.querySelectorAll('.w2calendar_date_disable');
    let disabledDays = [];
    for (var i = 0; i < disabledTds.length; i++) {
        disabledDays.push(disabledTds[i].textContent);
    }
    let firstClassName = disabledTds.length > 0 ? disabledTds[0].className : '';

    wf_body_bottom.getObj("scwin").setReturnValue("[호출] " + callLog);
    wf_body_bottom.getObj("scwin").setReturnValue("[비활성 날짜 일자] " + disabledDays.join(','));
    wf_body_bottom.getObj("scwin").setReturnValue("[첫 비활성 셀 className] '" + firstClassName + "' (w2calendar_date_disable 포함 여부: " + (firstClassName.indexOf('w2calendar_date_disable') !== -1 ? "예" : "아니오") + ")");
}



// gotoCase 별 분기 호출
// 1: setDisableBeforeDate('20251110') → 11/10 이전 비활성화 (validation 1, 2, 5)
// 2: setDisableBeforeDate('20251110') + enableAllDate() → 비활성화 해제 (validation 3)
// 3: calendarValueType=yearMonth 에서 setDisableBeforeDate('20251110') (validation 4)
// 4: setDisableBeforeDate('20251110') + gotoLastMonth() → 이전 월 탐색 가능 (validation 6)
// 5: setDisableBeforeDate('20251105') + setDisableAfterDate('20251125') → 11/05 이전 + 11/25 이후 모두 비활성 (validation 7 중복 적용)
scwin.btn_call_onclick = function (e) {
    let gotoCase = con_gotoCase.getValue();
    let callLog = "";

    if (gotoCase === "1") {
        // validation 1, 2, 5: 'yyyyMMdd' 8자리 문자열로 기준 날짜 설정, 이전 날짜에 w2calendar_date_disable 적용/취소선/선택 불가
        target1.setDisableBeforeDate("20251110");
        callLog = "target1.setDisableBeforeDate('20251110')";
    } else if (gotoCase === "3") {
        // validation 4: calendarValueType=yearMonth 에서 setDisableBeforeDate 설정 (UI 선택 제한 안 됨)
        // — 사전 조건: con_calendarValueType 을 'yearMonth' 로 변경 후 Target 재생성 필요
        target1.setDisableBeforeDate("20251110");
        callLog = "(calendarValueType=yearMonth) target1.setDisableBeforeDate('20251110')";
    } else if (gotoCase === "4") {
        // validation 6: setDisableBeforeDate 설정 후에도 년/월 탐색은 제한되지 않음 (gotoLastMonth 정상 동작)
        target1.setDisableBeforeDate("20251110");
        target1.gotoLastMonth();
        callLog = "target1.setDisableBeforeDate('20251110'); target1.gotoLastMonth();";
    } else if (gotoCase === "5") {
        // validation 7: 날짜 선택 제한 메소드(setDisableBeforeDate + setDisableAfterDate) 중복 적용
        target1.setDisableBeforeDate("20251105");
        target1.setDisableAfterDate("20251125");
        callLog = "target1.setDisableBeforeDate('20251105'); target1.setDisableAfterDate('20251125');";
    }

    scwin.getDisableInfo(callLog);
};
